mapper.select:
SELECT v.id as vlogId, v.vloger_id as vlogerId, u.face as vlogerFace, u.nickname as vlogerName, v.title as content, v.tag as tag, v.url as url, v.cover as cover, v.width as width, v.height as height, v.like_counts as likeCounts, v.comments_counts as commentsCounts, v.is_private as isPrivate FROM vlog v LEFT JOIN users u ON v.vloger_id = u.id LEFT JOIN ( SELECT va1.vlog_id, va1.audit_status FROM vlog_audit va1 INNER JOIN ( SELECT vlog_id, MAX(id) as max_id FROM vlog_audit GROUP BY vlog_id ) va2 ON va1.vlog_id = va2.vlog_id AND va1.id = va2.max_id ) latest_audit ON v.id = latest_audit.vlog_id WHERE v.id = #{paramMap.vlogId} AND (v.is_deleted = 0 OR v.is_deleted IS NULL) AND (u.is_deleted = 0 OR u.is_deleted IS NULL) AND ( latest_audit.audit_status = 1
OR v.vloger_id = #{paramMap.userId}
)
